Here is the root cause:
In functions ath11k_mac_setup_bcn_tmpl_ema() and ath11k_mac_setup_bcn_tmpl_mbssid(), memory allocated for beacon templates (via ieee80211_beacon_free_ema_list and kfree_skb) was not freed when parameter setup failed early, leading to memory leaks.

Here is the patch:

 static int ath11k_mac_setup_bcn_tmpl_ema(struct ath11k_vif *arvif,
 					 struct ath11k_vif *tx_arvif)
 {
 	struct ieee80211_ema_beacons *beacons;
 	int ret = 0;
 	bool nontx_vif_params_set = false;
 	u32 params = 0;
 	u8 i = 0;

 	beacons = ieee80211_beacon_get_template_ema_list(tx_arvif->ar->hw,
 							 tx_arvif->vif, 0);
 	if (!beacons || !beacons->cnt) {
 		ath11k_warn(arvif->ar->ab,
 			    "failed to get ema beacon templates from mac80211\n");
-		return -EPERM;
+		ret = -EPERM;
+		goto free;
 	}

 	if (tx_arvif == arvif) {
-		if (ath11k_mac_set_vif_params(tx_arvif, beacons->bcn[0].skb))
-			return -EINVAL;
+		if (ath11k_mac_set_vif_params(tx_arvif, beacons->bcn[0].skb)) {
+			ret = -EINVAL;
+			goto free;
+		}
 	} else {
 		arvif->wpaie_present = tx_arvif->wpaie_present;
 	}

 	for (i = 0; i < beacons->cnt; i++) {
 		if (tx_arvif != arvif && !nontx_vif_params_set)
 			nontx_vif_params_set =
 				ath11k_mac_set_nontx_vif_params(tx_arvif, arvif,
 								beacons->bcn[i].skb);

 		params = beacons->cnt;
 		params |= (i << WMI_EMA_TMPL_IDX_SHIFT);
 		params |= ((!i ? 1 : 0) << WMI_EMA_FIRST_TMPL_SHIFT);
 		params |= ((i + 1 == beacons->cnt ? 1 : 0) << WMI_EMA_LAST_TMPL_SHIFT);

 		ret = ath11k_wmi_bcn_tmpl(tx_arvif->ar, tx_arvif->vdev_id,
 					  &beacons->bcn[i].offs,
 					  beacons->bcn[i].skb, params);
 		if (ret) {
 			ath11k_warn(tx_arvif->ar->ab,
 				    "failed to set ema beacon template id %i error %d\n",
 				    i, ret);
 			break;
 		}
 	}

-	ieee80211_beacon_free_ema_list(beacons);
-
 	if (tx_arvif != arvif && !nontx_vif_params_set)
-		return -EINVAL; /* Profile not found in the beacons */
+		ret = -EINVAL; /* Profile not found in the beacons */

+free:
+	ieee80211_beacon_free_ema_list(beacons);
 	return ret;
 }

